WITH blk AS (SELECT DECODE(KODE_BA,'2122','2131',KODE_BA) ba, KODE_AFD afd, KODE_BLOK blok, DATE_TRUNC('month',BULAN)::DATE mo, MAX(COALESCE(NULLIF(TAHUN_TANAM,''),'?')) thn, MAX(COALESCE(NULLIF(MATURITY_STATUS,''),'?')) ms, SUM(COALESCE(HEKTAR_PANEN,0)) hp FROM PRD_DB_INTEGRATION.INT_PANEN.INT_HEKTAR_BLOK WHERE KODE_BA IN ('2121','2124','2131','2122') AND BULAN>='2026-01-01' AND BULAN<'2026-10-01' GROUP BY 1,2,3,4), tn AS (SELECT DECODE(KODE_BA,'2122','2131',KODE_BA) ba, KODE_AFD afd, KODE_BLOK blok, DATE_TRUNC('month',TANGGAL_PANEN)::DATE mo, SUM(TON_AKTUAL) ton FROM PRD_DB_INTEGRATION.INT_PANEN.INT_PENCAPAIAN_PRODUKSI_PANEN WHERE KODE_BA IN ('2121','2124','2131','2122') AND TANGGAL_PANEN>='2026-01-01' AND TANGGAL_PANEN<'2026-10-01' GROUP BY 1,2,3,4) SELECT COALESCE(b.ba,t.ba) ba, COALESCE(b.afd,t.afd) afd, COALESCE(b.thn,'?') thn, COALESCE(b.ms,'?') ms, ROUND(SUM(IFF(COALESCE(b.mo,t.mo)<'2026-09-01',COALESCE(t.ton,0),0)),2) ton_a, ROUND(SUM(IFF(COALESCE(b.mo,t.mo)='2026-09-01',COALESCE(t.ton,0),0)),2) ton_m, ROUND(SUM(IFF(COALESCE(b.mo,t.mo)<'2026-09-01',COALESCE(b.hp,0),0)),2) hp_a, ROUND(SUM(IFF(COALESCE(b.mo,t.mo)='2026-09-01',COALESCE(b.hp,0),0)),2) hp_m FROM blk b FULL OUTER JOIN tn t ON b.ba=t.ba AND b.afd=t.afd AND b.blok=t.blok AND b.mo=t.mo GROUP BY 1,2,3,4 HAVING SUM(COALESCE(t.ton,0))<>0 OR SUM(COALESCE(b.hp,0))<>0 ORDER BY 1,2,3,4